-- Schema v2 (docs/structure/schema-v2.dbml, steps 2 to 6) plus users.
-- Ids are 21-character NanoIds generated by the API.

-- identity

create table users
(
    id         varchar(21) primary key,
    role       varchar(255),
    created_at timestamptz not null,
    updated_at timestamptz not null
);

create table user_details
(
    id         varchar(21) primary key,
    user_id    varchar(21) not null unique references users (id),
    first_name varchar(255),
    last_name  varchar(255),
    index      varchar(255) unique,
    email      varchar(255) unique,
    password   varchar(72)
);

-- step 2: courses, exams, tasks and documents

create table courses
(
    id         varchar(21) primary key,
    code       varchar(255) not null unique,
    name       varchar(255) not null,
    active     boolean      not null default true,
    created_at timestamptz  not null,
    updated_at timestamptz  not null
);

create table exams
(
    id         varchar(21) primary key,
    course_id  varchar(21)  not null references courses (id),
    name       varchar(255) not null,
    starts_at  timestamptz  not null,
    ends_at    timestamptz  not null,
    created_at timestamptz  not null,
    updated_at timestamptz  not null
);

-- step 6: groups (before tasks, which point at them)

create table exam_groups
(
    id         varchar(21) primary key,
    exam_id    varchar(21)  not null references exams (id),
    name       varchar(255) not null,
    sort_order int          not null default 0,
    created_at timestamptz  not null,
    updated_at timestamptz  not null,
    constraint uq_exam_groups_exam_name unique (exam_id, name)
);

-- step 4: datasets (before tasks, which point at them)

create table datasets
(
    id         varchar(21) primary key,
    exam_id    varchar(21)  not null references exams (id),
    name       varchar(255) not null,
    ddl        text         not null,
    created_at timestamptz  not null,
    updated_at timestamptz  not null
);

create table tasks
(
    id             varchar(21) primary key,
    exam_id        varchar(21)  not null references exams (id),
    group_id       varchar(21) references exam_groups (id),
    type           varchar(255) not null,
    data_source    varchar(255),
    source_task_id varchar(21) references tasks (id),
    dataset_id     varchar(21) references datasets (id),
    solution       text,
    title          varchar(255) not null,
    description    text         not null,
    points         int          not null,
    sort_order     int          not null,
    created_at     timestamptz  not null,
    updated_at     timestamptz  not null
);

create table folders
(
    id         varchar(21) primary key,
    course_id  varchar(21)  not null references courses (id),
    name       varchar(255) not null,
    created_at timestamptz  not null,
    updated_at timestamptz  not null
);

create table documents
(
    id         varchar(21) primary key,
    folder_id  varchar(21) references folders (id),
    name       varchar(255) not null,
    content_md text,
    file_path  varchar(255),
    url        varchar(255),
    mime_type  varchar(255),
    size_bytes int,
    sort_order int          not null default 0,
    created_at timestamptz  not null,
    updated_at timestamptz  not null
);

create table exam_folders
(
    id         varchar(21) primary key,
    exam_id    varchar(21) not null references exams (id),
    folder_id  varchar(21) not null references folders (id),
    sort_order int         not null default 0,
    constraint uq_exam_folders_exam_folder unique (exam_id, folder_id)
);

create table task_documents
(
    id          varchar(21) primary key,
    task_id     varchar(21) not null references tasks (id),
    document_id varchar(21) not null references documents (id),
    sort_order  int         not null default 0,
    constraint uq_task_documents_task_document unique (task_id, document_id)
);

-- step 3: task objects

create table task_objects
(
    id         varchar(21) primary key,
    task_id    varchar(21)  not null references tasks (id),
    kind       varchar(255) not null,
    name       varchar(255) not null,
    arguments  varchar(255),
    on_table   varchar(255),
    sort_order int          not null default 0,
    constraint uq_task_objects_task_name unique (task_id, name)
);

-- step 4: dataset versions and the versions that test a task

create table dataset_versions
(
    id          varchar(21) primary key,
    dataset_id  varchar(21)  not null references datasets (id),
    name        varchar(255) not null,
    visible     boolean      not null default false,
    document_id varchar(21)  not null references documents (id),
    sort_order  int          not null default 0,
    created_at  timestamptz  not null,
    updated_at  timestamptz  not null,
    constraint uq_dataset_versions_dataset_name unique (dataset_id, name)
);

-- at most one visible version per dataset
create unique index uq_dataset_versions_one_visible on dataset_versions (dataset_id) where visible;

create table task_versions
(
    id         varchar(21) primary key,
    task_id    varchar(21) not null references tasks (id),
    version_id varchar(21) not null references dataset_versions (id),
    constraint uq_task_versions_task_version unique (task_id, version_id)
);

-- step 5: test steps for CODE tasks

create table test_steps
(
    id           varchar(21) primary key,
    task_id      varchar(21) not null references tasks (id),
    sort_order   int         not null,
    action_sql   text        not null,
    expect_error boolean     not null default false,
    check_sql    text,
    created_at   timestamptz not null,
    updated_at   timestamptz not null,
    constraint uq_test_steps_task_sort_order unique (task_id, sort_order)
);

create table expected_results
(
    id          varchar(21) primary key,
    task_id     varchar(21)  not null references tasks (id),
    version_id  varchar(21)  not null references dataset_versions (id),
    step_id     varchar(21) references test_steps (id),
    hash        varchar(255) not null,
    computed_at timestamptz  not null,
    constraint uq_expected_results_task_version_step unique (task_id, version_id, step_id)
);

-- QUERY results have no step: one per task and version
create unique index uq_expected_results_task_version_no_step on expected_results (task_id, version_id) where step_id is null;
